-- BIZFORGE LLC FULL CORPORATE V4 + CMS + SUPPORT
create extension if not exists pgcrypto;

create table if not exists public.inquiries(
 id bigint generated by default as identity primary key,created_at timestamptz not null default now(),name text not null,email text not null,company text,service text,budget text,message text not null,request_type text default 'inquiry');
alter table public.inquiries enable row level security;
drop policy if exists "public submit inquiries" on public.inquiries;
create policy "public submit inquiries" on public.inquiries for insert to anon with check(true);
drop policy if exists "admin read inquiries" on public.inquiries;
create policy "admin read inquiries" on public.inquiries for select to authenticated using(true);

create table if not exists public.site_settings(
 id integer primary key default 1 check(id=1),business_name text not null default 'BizForge LLC',tagline text not null default 'IT • SOFTWARE • AI • AUTOMATION',
 hero_title text not null default 'Corporate technology delivery for modern business.',hero_subtitle text not null default 'Websites, custom software, AI automation, cloud deployment and ongoing support—from clear scope to launch and handoff.',
 contact_email text not null default '',contact_phone text not null default '',business_address text not null default '',office_hours text not null default '',
 developer_credit text not null default 'Technology implementation & support by OMS IT',meta_title text not null default 'BizForge LLC | IT, Software & AI Solutions',
 meta_description text not null default 'BizForge LLC provides web development, custom software, AI automation, cloud deployment and ongoing IT support.',updated_at timestamptz default now());
insert into public.site_settings(id)values(1)on conflict(id)do nothing;
alter table public.site_settings enable row level security;
drop policy if exists "public read settings" on public.site_settings;create policy "public read settings" on public.site_settings for select to anon,authenticated using(true);
drop policy if exists "admin settings" on public.site_settings;create policy "admin settings" on public.site_settings for all to authenticated using(true)with check(true);

create table if not exists public.cms_services(id bigint generated by default as identity primary key,slug text unique,title text not null,description text not null default '',long_description text not null default '',starting_price text not null default '',icon text not null default '◫',features jsonb not null default '[]',deliverables jsonb not null default '[]',ideal_for jsonb not null default '[]',timeline_note text not null default '',sort_order int not null default 0,is_active boolean not null default true);
create table if not exists public.cms_pricing(id bigint generated by default as identity primary key,name text not null,subtitle text not null default '',starting_price text not null default '',features jsonb not null default '[]',sort_order int not null default 0,is_featured boolean not null default false,is_active boolean not null default true);
create table if not exists public.cms_team(id bigint generated by default as identity primary key,name text not null,role text not null default '',bio text not null default '',photo_url text not null default '',sort_order int not null default 0,is_active boolean not null default true);
create table if not exists public.cms_reviews(id bigint generated by default as identity primary key,reviewer_name text not null,company text not null default '',quote text not null,rating int not null default 5 check(rating between 1 and 5),sort_order int not null default 0,verified boolean not null default false,is_active boolean not null default true);
create table if not exists public.cms_experience(id bigint generated by default as identity primary key,title text not null,category text not null default '',summary text not null default '',details text not null default '',sort_order int not null default 0,is_active boolean not null default true);
create table if not exists public.cms_page_blocks(id bigint generated by default as identity primary key,page_key text not null,title text not null,subtitle text not null default '',body text not null default '',sort_order int not null default 0,is_active boolean not null default true);

do $$ declare t text; begin foreach t in array array['cms_services','cms_pricing','cms_team','cms_reviews','cms_experience','cms_page_blocks'] loop execute format('alter table public.%I enable row level security',t); execute format('drop policy if exists "public_read_%s" on public.%I',t,t); execute format('create policy "public_read_%s" on public.%I for select to anon,authenticated using(is_active=true or auth.role()=''authenticated'')',t,t); execute format('drop policy if exists "admin_manage_%s" on public.%I',t,t); execute format('create policy "admin_manage_%s" on public.%I for all to authenticated using(true) with check(true)',t,t); end loop; end $$;

