-- Support chat: direct anon access is blocked; visitors use tokenized RPC functions.
create table if not exists public.support_sessions(id bigint generated by default as identity primary key,token uuid not null unique default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),name text not null,email text not null,status text not null default 'open');
create table if not exists public.support_messages(id bigint generated by default as identity primary key,session_id bigint not null references public.support_sessions(id) on delete cascade,sender text not null check(sender in('visitor','agent')),message text not null,created_at timestamptz not null default now());
alter table public.support_sessions enable row level security;alter table public.support_messages enable row level security;
drop policy if exists "admin support sessions" on public.support_sessions;create policy "admin support sessions" on public.support_sessions for all to authenticated using(true)with check(true);
drop policy if exists "admin support messages" on public.support_messages;create policy "admin support messages" on public.support_messages for all to authenticated using(true)with check(true);

create or replace function public.create_support_session(p_name text,p_email text)returns uuid language plpgsql security definer set search_path=public as $$declare t uuid;begin insert into support_sessions(name,email)values(left(trim(p_name),120),left(trim(p_email),320))returning token into t;return t;end$$;
grant execute on function public.create_support_session(text,text) to anon,authenticated;

create or replace function public.send_support_message(p_token uuid,p_message text)returns void language plpgsql security definer set search_path=public as $$declare sid bigint;begin select id into sid from support_sessions where token=p_token;if sid is null then raise exception 'Invalid support session';end if;if length(trim(p_message))<1 or length(p_message)>4000 then raise exception 'Invalid message length';end if;insert into support_messages(session_id,sender,message)values(sid,'visitor',trim(p_message));update support_sessions set updated_at=now(),status='open' where id=sid;end$$;
grant execute on function public.send_support_message(uuid,text) to anon,authenticated;

create or replace function public.get_support_messages(p_token uuid)returns table(id bigint,sender text,message text,created_at timestamptz) language sql security definer set search_path=public as $$select m.id,m.sender,m.message,m.created_at from support_messages m join support_sessions s on s.id=m.session_id where s.token=p_token order by m.created_at$$;
grant execute on function public.get_support_messages(uuid) to anon,authenticated;
